package com.johnny.hotel.cms;
import com.johnny.hotel.exception.BusinessException;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.nio.file.*;
@RestController@RequestMapping("/api/public/site/media")public class PublicMediaController{private final Path root;private final CmsService service;public PublicMediaController(@Value("${hotel.cms.media.local-root:./data/cms-media}")String root,CmsService service){this.root=Path.of(root).toAbsolutePath().normalize();this.service=service;}@GetMapping("/{key}")public ResponseEntity<Resource>get(@PathVariable String key){if(!key.matches("[0-9a-fA-F-]{36}\\.(jpg|jpeg|png|webp|mp4|webm|glb|gltf)"))throw new BusinessException(404,"Media not found");var media=service.publicMedia(key);Path p=root.resolve(media.getStorageKey()).normalize();if(!p.getParent().equals(root)||!Files.isRegularFile(p))throw new BusinessException(404,"Media not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(media.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline").header("X-Content-Type-Options","nosniff").body(new FileSystemResource(p));}}
